pragma solidity >=0.8.0;
contract PackedEmptyStr {
    event Packed(bytes data, bytes32 k, bytes32 s);
    uint256 public lastLen;

    function packEmpty() public returns (uint256) {
        bytes memory p = abi.encodePacked(uint8(1), uint16(2), uint64(3), uint256(4), "");
        lastLen = p.length;
        emit Packed(p, keccak256(p), sha256(p));
        return p.length;
    }

    function packX() public returns (uint256) {
        bytes memory p = abi.encodePacked(uint8(1), uint16(2), uint64(3), uint256(4), "x");
        lastLen = p.length;
        emit Packed(p, keccak256(p), sha256(p));
        return p.length;
    }

    function packOnlyEmpty() public returns (uint256) {
        bytes memory p = abi.encodePacked("");
        lastLen = p.length;
        emit Packed(p, keccak256(p), sha256(p));
        return p.length;
    }

    function packOnlyX() public returns (uint256) {
        bytes memory p = abi.encodePacked("x");
        lastLen = p.length;
        emit Packed(p, keccak256(p), sha256(p));
        return p.length;
    }
}
